// DOM/mock integration; fixture was generated by the real Python contract.
import {test} from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import {parseHTML} from 'linkedom';
import {createRecommendations} from '../frontend/recommendations.js';import {setLanguage,installLanguageUI,disposeLanguageUI} from '../frontend/i18n.js';
const fixture=JSON.parse(await fs.readFile(new URL('./fixtures/recommendation-contract.json',import.meta.url),'utf8'));
const flush=async()=>{for(let i=0;i<6;i++)await new Promise(r=>setImmediate(r));};
function setup(overrides={}){
 const {window}=parseHTML('<html><body></body></html>');globalThis.window=window;globalThis.document=window.document;
 Object.defineProperty(window.HTMLSelectElement.prototype,'value',{configurable:true,get(){return this._value??this.querySelector('option')?.value??'';},set(v){this._value=String(v);}});
 const calls=[],chosen=[],closed=[];let guest=false,login=0;
 const api=async(path,options)=>{calls.push({path,options});return path.endsWith('/schema')?structuredClone(fixture.contract):structuredClone(fixture.cases[JSON.parse(options.body).template_id]);};
 const ui=createRecommendations({api,isAuthenticated:()=>!guest,login:()=>login++,onSelect:async(value,request)=>chosen.push({value,request}),onClose:value=>closed.push(value),...overrides});
 const dialog=document.querySelector('#recommendations-dialog');dialog.showModal=()=>dialog.setAttribute('open','');dialog.close=()=>dialog.removeAttribute('open');
 const $=q=>dialog.querySelector(q),change=(q,value)=>{$(q).value=value;$(q).dispatchEvent(new window.Event('input',{bubbles:true}));$(q).dispatchEvent(new window.Event('change',{bubbles:true}));};
 return {ui,$,calls,chosen,closed,change,submit:()=>$('#rec-form').onsubmit({preventDefault(){}}),guest:()=>{guest=true;},logins:()=>login};
}
test('guest help opens login and sends no recommendation or protected request',async()=>{
 const f=setup();f.guest();await f.ui.open();assert.equal(f.logins(),1);assert.equal(f.calls.length,0);f.ui.dispose();
});
test('all nine templates use backend fields, with Unknown initially and no auto-create/quote',async()=>{
 await setLanguage('en',{persist:false});const f=setup();
 for(const tid of Object.keys(fixture.contract.templates)){
  await f.ui.open({templateId:tid});assert.equal(f.calls.at(-1).path,'/recommendations/schema');
  assert.deepEqual([...document.querySelectorAll('[data-workload]')].map(el=>el.dataset.workload).sort(),fixture.contract.templates[tid].fields.map(x=>x.key).sort());
  assert.ok(Object.values(f.ui.snapshot().request.workload).every(x=>x===null));
  f.$('#rec-example').click();await f.submit();assert.equal(f.calls.at(-1).path,'/recommendations');
  assert.match(f.$('#rec-results').textContent,/no matching load benchmark|More information needed/);assert.doesNotMatch(f.$('#rec-results').textContent,/Unavailable/);
  assert.equal(f.chosen.length,0);f.ui.close();
 }
 assert.ok(f.calls.every(call=>!['/environments','/estimates'].includes(call.path)));f.ui.dispose();
});
test('selection passes exact backend defaults but leaves quote and creation to the existing flow',async()=>{
 const f=setup();await f.ui.open({templateId:'T01'});f.$('#rec-example').click();await f.submit();f.$('#rec-results .rec-option button').click();await flush();
 assert.equal(f.chosen.length,1);assert.equal(f.chosen[0].value.profile_id,'standard');assert.equal(f.chosen[0].value.creation_defaults.planning_workload.data_mib,1024);
 assert.equal(f.chosen[0].request.workload.min_memory_mib,512);assert.equal(f.closed.at(-1).selected,true);assert.equal(f.calls.length,2);f.ui.dispose();
});
test('changing inputs discards late responses and does not resurrect a stale selection',async()=>{
 let resolve;const f=setup({api:async path=>path.endsWith('/schema')?structuredClone(fixture.contract):new Promise(r=>resolve=r)});
 await f.ui.open();f.$('#rec-example').click();const pending=f.submit();f.change('#rec-region','ap-northeast-1');resolve(structuredClone(fixture.cases.T01));await pending;
 assert.equal(f.$('#rec-results').textContent,'');assert.equal(f.ui.snapshot().last,null);assert.equal(f.ui.snapshot().request.region,'ap-northeast-1');f.ui.dispose();
});
test('language changes retain demand, deployment Region and selected profile',async()=>{
 const f=setup();await f.ui.open({templateId:'T07',region:'ap-northeast-1',profileId:'expanded',assess:true});f.change('#rec-input-data_kib','100');
 await setLanguage('de',{persist:false,loader:async()=>JSON.parse(await fs.readFile(new URL('../frontend/locales/de.json',import.meta.url),'utf8'))});
 const s=f.ui.snapshot().request;assert.equal(s.region,'ap-northeast-1');assert.equal(s.profile_id,'expanded');assert.equal(s.workload.data_kib,100);assert.match(f.$('#rec-title').textContent,/Konfiguration/);f.ui.dispose();await setLanguage('en',{persist:false});
});
test('unknown price remains unknown and disables selection rather than showing zero cost',async()=>{
 const result=structuredClone(fixture.cases.T07);result.options[0].cost.total_milliusd=null;result.options[0].budget_status='UNKNOWN';result.options[0].can_select=false;result.status='NO_MATCH';
 const f=setup({api:async path=>path.endsWith('/schema')?structuredClone(fixture.contract):result});await f.ui.open({templateId:'T07'});await f.submit();assert.equal(f.$('#rec-results .rec-option button').disabled,true);assert.match(f.$('#rec-results').textContent,/Incomplete estimate/);f.ui.dispose();
});
test('error and retry retain form values; closing fences a pending request',async()=>{
 let attempts=0;const f=setup({api:async path=>{if(path.endsWith('/schema'))return structuredClone(fixture.contract);if(++attempts===1)throw Object.assign(Error('synthetic offline'),{code:'LOCAL_OFFLINE'});return structuredClone(fixture.cases.T01);}});
 await f.ui.open();f.change('#rec-input-data_mib','456');await f.submit();assert.equal(f.$('#rec-input-data_mib').value,'456');assert.match(f.$('#rec-notice').textContent,/LOCAL_OFFLINE/);await f.submit();assert.equal(f.$('#rec-input-data_mib').value,'456');assert.ok(f.$('#rec-results .rec-option'));f.ui.dispose();
});
test('assessment preserves lifecycle and exact configuration without opting into renewal',async()=>{
 const f=setup();await f.ui.open({templateId:'T05',region:'ap-southeast-1',profileId:'expanded',assess:true,form:{mode:'AUTO_OFF',periodMinutes:'15',estimateHours:'4',endingPolicy:'PAUSE'}});
 const r=f.ui.snapshot().request;assert.equal(r.mode,'ASSESS');assert.equal(r.operating_policy.mode,'AUTO_OFF');assert.equal(r.operating_policy.period_minutes,15);assert.equal(r.operating_policy.ending_policy,'PAUSE');assert.equal(r.operating_policy.confirmed,undefined);f.ui.dispose();
});

test('owned dialog translations work with the legacy page translator without resetting inputs',async()=>{
 const f=setup();installLanguageUI(document);await f.ui.open({templateId:'T07'});f.change('#rec-input-data_kib','123');
 await setLanguage('fr',{persist:false,loader:async code=>JSON.parse(await fs.readFile(new URL('../frontend/locales/'+code+'.json',import.meta.url),'utf8'))});
 assert.match(f.$('#rec-title').textContent,/configuration/i);assert.equal(f.$('#rec-input-data_kib').value,'123');assert.equal(f.$('#rec-region').value,'ap-southeast-1');assert.match(f.$('[data-language-select]').getAttribute('aria-label'),/Langue/);
 f.ui.dispose();disposeLanguageUI();await setLanguage('en',{persist:false});
});
